<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;use App\Services\DanceCupScoringService;Auth::requireAdmin();$pdo=Database::connection();$test=(string)($_GET['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin required.');}$t=DanceCupScoringService::tables($test);$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT c.*,e.name event_name,e.event_date FROM {$t['competitions']} c JOIN {$t['events']} e ON e.id=c.event_id WHERE c.id=:id");$q->execute(['id'=>$id]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Dance Cup category not found.');}$q=$pdo->prepare("SELECT * FROM {$t['criteria']} WHERE competition_id=:id ORDER BY sort_order,id");$q->execute(['id'=>$id]);$criteria=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['category_name'])?> | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=317" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:1100px"><a href="./<?=$test?'?data_mode=test':''?>">← Dance Cup Dashboard</a><section class="card border-0 shadow-sm mt-3"><div class="card-body p-4"><span class="badge text-bg-secondary"><?=e(strtoupper($c['status']))?></span><h1 class="h3 mt-2"><?=e($c['category_name'])?></h1><p class="text-muted"><?=e($c['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?> · <?=e(ucwords(str_replace('_',' ',$c['competition_level'])))?> · <?=e(ucfirst($c['entry_type']))?> · <?=e(ucfirst($c['round_name']))?></p><h2 class="h5 mt-4">Scoring Criteria</h2><table class="table"><thead><tr><th>Criterion</th><th>Maximum</th></tr></thead><tbody><?php foreach($criteria as $x):?><tr><td><?=e($x['criterion_name'])?></td><td><?=number_format((float)$x['maximum_points'],2)?></td></tr><?php endforeach;?></tbody></table><div class="alert alert-info mb-0"><strong>Draft opened.</strong> This category workspace is ready for the next competitor, judge, scoring, results and Projection controls.</div></div></section></main></body></html>
